window.AUTH=window.AUTH||{};window.AUTH["08-1498"]={"d":"08-1498","id":"2009/08-1498","n":"Holder v. Humanitarian Law Project","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondents","date":"","url":"https://www.justice.gov/osg/media/202276/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/holder-v-humanitarian-law-projhumanitarian-law-proj-v-holder-brief-merits","n":132}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep561/usrep561001/usrep561001.pdf","tr":true,"items":[{"t":"case","label":"American Commc’ns Ass’n v. Douds","cite":"339 U.S. 382","y":1950,"id":"1940-1955/339us382","sc":1,"sum":"Section 9 (h) of the National Labor Relations Act, as amended b3 the Labor Management Relations Act, 1947, which imposes certain restrictions on, and denies the benefits of certain provisions of the National Labor Relations Act to, any labor organization the officers of which have not filed with the National Labor Relations Board the so-called \"non-Communist\" affidavits prescribed by § 9 (h), is valid under the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 32"}},{"t":"case","label":"Board of Governors of the Fed. Reserve Sys. v. Agnew","cite":"329 U.S. 441","y":1947,"id":"scdb/1946-031","sc":1,"sum":"The partnership was \"primarily engaged\" in the underwriting and distribution of securities within the meaning of § 32 of the Act and its employees were disqualified from serving as directors of a member bank of the Federal Reserve System.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Boim v. Holy Land Found. for Relief & Dev.","cite":"549 F.3d 685","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/549/685/","by":{"0":"48, 56"}},{"t":"case","label":"Boim v. Quranic Literacy Inst.","cite":"291 F.3d 1000","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/291/1000/","by":{"0":"48"}},{"t":"case","label":"Boy Scouts of Am. v. Dale","cite":"530 U.S. 640","y":2000,"id":"1999/99-699","sc":1,"sum":"The Court held that the Boy Scouts of America banning openly homosexual members was constitutional under the First Amendment.","sumSrc":"Oyez","by":{"0":"61"}},{"t":"case","label":"California Teachers Ass’n v. State Bd. of Educ.","cite":"271 F.3d 1141","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/271/1141/","sum":"Holding that “instruction” is a “word[] of common understanding” and is not unconstitutionally vague.","sumSrc":"brief:0","by":{"0":"20"}},{"t":"case","label":"Cannon v. University of Chi.","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"65"}},{"t":"case","label":"Carter v. United States","cite":"530 U.S. 255","y":2000,"id":"1999/99-5716","sc":1,"sum":"The Court held that federal bank larceny is not a \"lesser included offense\" of federal bank robbery. The \"[p]etitioner is accordingly prohibited as a matter of law from obtaining a lesser included offense instruction,\" wrote Justice Thomas for the Court.","sumSrc":"Oyez","by":{"0":"66"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"532 U.S. 105","y":2001,"id":"2000/99-1379","sc":1,"op":10,"sum":"The Court held that section 1 exemption is confined to transportation workers. \"The wording of [section 1] calls for the application of the maxim ejusdem generis, the statutory canon that 'where general words follow specific words in a statutory enumeration, the general words are construed to embrace only objects similar in nature to those objects enumerated by the preceding specific words,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"City of Erie v. Pap’s A.M.","cite":"529 U.S. 277","y":2000,"id":"1999/98-1161","sc":1,"sum":"The Court held that Erie's public indecency ordinance did not violate any cognizable First Amendment protections of expressive conduct.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"City of L.A. v. Alameda Books, Inc.","cite":"535 U.S. 425","y":2002,"id":"2001/00-799","sc":1,"sum":"The Court held that the city of Los Angeles may reasonably rely on a study it conducted some years before enacting the present version of section 12.70(C) to demonstrate that its ban on multiple-use adult establishments serves its interest in reducing crime. Three other Justices joined in this holding.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Coates v. City of Cincinnati","cite":"402 U.S. 611","y":1971,"id":"1970/117","sc":1,"ar":1,"sum":"Cincinnati, Ohio, ordinance making it a criminal offense for \"three or more persons to assemble... on any of the sidewalks... and there conduct themselves in a manner annoying to persons passing by...,\" which has not been narrowed by any construction of the Ohio Supreme Court, held violative on its face of the due process standard of vagueness and the constitutional right of free assembly and association. Pp. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Cohen v. California","cite":"403 U.S. 15","y":1971,"id":"1970/299","sc":1,"op":7,"ar":2,"sum":"The Court ruled that a California statute prohibiting the display of offensive messages such as \"F--- the Draft\" violated freedom of expression as protected by the First Amendment.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Cox Broad. Corp. v. Cohn","cite":"420 U.S. 469","y":1975,"id":"1974/73-938","sc":1,"sum":"The Court held that the Georgia statute violated the Constitution. Justice White recognized the primacy of issues of privacy and press freedom, but he also identified compelling reasons why the press should not be restricted in this case. First, the news media is an important resource for citizens which allows them to scrutinize government proceedings.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"DKT Mem’l Fund Ltd. v. Agency for Int’l Dev.","cite":"887 F.2d 175","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/887/175/","by":{"0":"52"}},{"t":"case","label":"Daubert v. Merrell Dow Pharms., Inc.","cite":"509 U.S. 579","y":1993,"id":"1992/92-102","sc":1,"sum":"Petitioners, two minor children and their parents, alleged in their suit against respondent that the children's serious birth defects had been caused by the mothers' prenatal ingestion of Bendectin, a prescription drug marketed by respondent. The District Court granted respondent summary judgment based on a well-credentialed expert's affidavit concluding, upon reviewing the extensive published scientific literature …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"De Jonge v. Oregon","cite":"299 U.S. 353","y":1937,"id":"1900-1940/299us353","sc":1,"op":5,"ar":3,"sum":"Describing the “right of peaceable assembly” as “a right cognate to those of free speech and free press and . . . equally fundamental”.","sumSrc":"opinion","by":{"0":"60, 61"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Florida Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Elrod v. Burns","cite":"427 U.S. 347","y":1976,"id":"1975/74-1520","sc":1,"sum":"The judgment is affirmed. Pp. 351-374; 374-375. 509 F. 2d 1133, affirmed. MR. JUSTICE BRENNAN, joined by MR. JUSTICE WHITE and MR. JUSTICE MARSHALL, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"61"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"129 S. Ct. 1800","y":2009,"id":"2008/07-582","sc":1,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"0":"63"}},{"t":"case","label":"FCC v. League of Women Voters","cite":"468 U.S. 364","y":1984,"id":"1983/82-912","sc":1,"op":2,"sum":"Even though the Commerce Clause gives Congress the power to regulate the broadcast medium, \"since broadcasters are engaged in a vital and independent form of communicative activity,\" Congress must use the First Amendment to \"inform and give shape\" to its regulation.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Fisher v. City of Berkeley","cite":"475 U.S. 260","y":1986,"id":"1985/84-1538","sc":1,"sum":"The ordinance is not unconstitutional as being pre-empted by the Sherman Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Gentile v. State Bar","cite":"501 U.S. 1030","y":1991,"id":"1990/89-1836","sc":1,"op":2,"sum":"The judgment is reversed. 106 Nev. 60, 787 P. 2d 386, reversed. JUSTICE KENNEDY delivered the opinion of the Court with respect to Parts III and VI, concluding that, as interpreted by the Nevada Supreme Court, Rule 177 is void for vagueness. Its safe harbor provision, Rule 177(3), misled Gentile into thinking that he could give his press conference without fear of discipline. Given the Rule's grammatical structure …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24"}},{"t":"case","label":"Grayned v. City of Rockford","cite":"408 U.S. 104","y":1972,"id":"1971/70-5106","sc":1,"op":1,"sum":"Rejecting a vague­ ness challenge to a criminal law that implicated First Amendment activities.","sumSrc":"opinion","by":{"0":"16, 17, 25, 43"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"op":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Haig v. Agee","cite":"453 U.S. 280","y":1981,"id":"1980/80-83","sc":1,"op":1,"sum":"In a 7-to-2 decision, the Court held that Passport Act of 1926 and other congressional statutes implicitly granted the Secretary of State the power to revoke passports.","sumSrc":"Oyez","by":{"0":"57"}},{"t":"case","label":"Harris v. United States","cite":"536 U.S. 545","y":2002,"id":"2001/00-10666","sc":1,"sum":"The Court held that section 924(c)(1)(A) defines a single offense, in which brandishing a firearm is a sentencing factor to be found by the judge, not an offense element to be found by the jury.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Hill v. Colorado","cite":"530 U.S. 703","y":2000,"id":"1999/98-1856","sc":1,"op":2,"sum":"The Court held that a statute requiring speakers within 100 feet of a medical facility to obtain consent before speaking, using signs, or distributing leaflets does not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"18, 25, 51"}},{"t":"case","label":"Humanitarian Law Project v. Ashcroft","cite":"532 U.S. 904","y":2001,"url":"https://supreme.justia.com/cases/federal/us/532/904/","sc":1,"by":{"0":"9"}},{"t":"case","label":"Humanitarian Law Project v. Reno","cite":"205 F.3d 1130","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/205/1130/","op":3,"by":{"0":"passim"}},{"t":"case","label":"Humanitarian Law Project v. United States Treasury Dep’t","cite":"578 F.3d 1133","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/578/1133/","sum":"Rejecting vagueness challenge to an Executive Order that permits the Secretary of the Treasury to designate entities that provide “financial or other services to or in support of ” acts of terrorism.","sumSrc":"brief:0","by":{"0":"38"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"sum":"The Court ruled 5-3 that attempted burglary is a \"violent felony\" for purposes of the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Jarecki v. G.D. Searle & Co.","cite":"367 U.S. 303","y":1961,"id":"1960/151","sc":1,"op":4,"sum":"1. Development of new products is not \"discovery\" within the meaning of § 456 (a) (2) (B) of the Internal Revenue Code of 1939, as amended; and income resulting from the manufacture and sale of certain patented drugs, cameras, camera equipment and stereo products resulting from inventions is not included within the statutory definition of \"abnormal income,\" in § 456 (a), so as to qualify for Korean War excess …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Keyishian v. Board of Regents of the Univ. of the State of N.Y.","cite":"385 U.S. 589","y":1967,"id":"1966/105","sc":1,"op":2,"sum":"The Court held that the provisions of the New York plan were defined in such uncertain terms that they infringed upon the constitutional rights of public servants.","sumSrc":"Oyez","by":{"0":"60"}},{"t":"case","label":"Kumho Tire Co. v. Carmichael","cite":"526 U.S. 137","y":1999,"id":"1998/97-1709","sc":1,"sum":"The Court held that a federal trial judge's \"gatekeeping\" obligation applies not only to \"scientific\" testimony, but to all expert testimony. Justice Breyer wrote for the Court that Federal Rule of Evidence 702 \"makes no relevant distinction between 'scientific' knowledge and 'technical' or 'other specialized knowledge.","sumSrc":"Oyez","by":{"0":"29, 32, 33"}},{"t":"case","label":"Lorillard Tobacco Co. v. Reilly","cite":"533 U.S. 525","y":2001,"id":"2000/00-596","sc":1,"sum":"The highly fractured Court held that the FCLAA preempts Massachusetts' regulations governing outdoor and point-of-sale cigarette advertising and that Massachusetts' outdoor and point-of-sale advertising regulations related to smokeless tobacco and cigars violate the First Amendment, but that the sales practices regulations related to all three tobacco products are constitutional. \"We conclude that the Attorney General has failed to show that the outdoor advertising regulations for smokeless tobacco and cigars are not more extensive than necessary to advance the State's substantial interest in preventing underage tobacco use,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"McConnell v. Federal Election Comm’n","cite":"540 U.S. 93","y":2003,"id":"2003/02-1674","sc":1,"sum":"The Court found that regulations in the Campaign Finance Reform Act of 2002 did not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"McIntyre v. Ohio Elections Comm’n","cite":"514 U.S. 334","y":1995,"id":"1994/93-986","sc":1,"sum":"The freedom to publish anonymously is protected by the First Amendment and \"extends beyond the literary realm to the advocacy of political causes.\" When a law burdens such anonymous speech, the Court applies \"exacting scrutiny,\" upholding the restriction only if it is narrowly tailored to serve an overriding state interest.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Monsanto Co. v. Spray-Rite Serv. Corp.","cite":"465 U.S. 752","y":1984,"id":"1983/82-914","sc":1,"sum":"From 1957 to 1968, respondent, a wholesale distributor of agricultural chemicals that engaged in a discount operation, sold agricultural herbicides manufactured by petitioner. In 1968, petitioner refused to renew respondent's 1-year distributorship term, and thereafter respondent was unable to purchase from other distributors as much of petitioner's products as it desired or as early in the season as it needed them. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"NAACP v. Claiborne Hardware Co.","cite":"458 U.S. 886","y":1982,"id":"1981/81-202","sc":1,"op":2,"sum":"The Court held that the NAACP's nonviolent protest was protected by the First Amendment.","sumSrc":"Oyez","by":{"0":"60"}},{"t":"case","label":"NCAA v. Smith","cite":"525 U.S. 459","y":1999,"id":"1998/98-84","sc":1,"sum":"The Court held that dues payments from recipients of federal funds do not suffice to subject the NCAA to suit under Title IX.","sumSrc":"Oyez","by":{"0":"63"}},{"t":"case","label":"Noto v. United States","cite":"367 U.S. 290","y":1961,"id":"1960/9","sc":1,"op":4,"sum":"The judgment is reversed, because the evidence was insufficient to prove that the Communist Party presently advocated forcible overthrow of the Government, not as an abstract doctrine, but by the use of language reasonably and ordinarily calculated to incite persons to action, immediately or in the future.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"60"}},{"t":"case","label":"Parker v. Levy","cite":"417 U.S. 733","y":1974,"id":"1973/73-206","sc":1,"op":2,"sum":"Article 90 (2) of the Uniform Code of Military Justice (Code) provides for punishment of any person subject to the Code who \"willfully disobeys a lawful command of his superior commissioned officer\"; Art. 133 punishes a commissioned officer for \"conduct unbecoming an officer and a gentleman\"; and Art. 134 (the general article) punishes any person subject to the Code for, inter alia, \"all disorders and neglects to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 26, 34"}},{"t":"case","label":"People’s Mojahedin Org. of Iran v. Department of State","cite":"327 F.3d 1238","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/327/1238/","by":{"0":"48"}},{"t":"case","label":"People’s Mojahedin Org. of Iran v. United States Dep’t of State","cite":"182 F.3d 17","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/182/17/","op":1,"by":{"0":"5, 6, 50"}},{"t":"case","label":"Pierce v. Underwood","cite":"487 U.S. 552","y":1988,"id":"1987/86-1512","sc":1,"sum":"One of petitioner's predecessors as Secretary of Housing and Urban Development decided not to implement an \"operating subsidy\" program authorized by federal statute, which was intended to provide payments to owners of Government-subsidized apartment buildings to offset rising utility expenses and property taxes. Various plaintiffs, including respondent members of a nationwide class of Government-subsidized housing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 24"}},{"t":"case","label":"Posters ‘N’ Things, Ltd. v. United States","cite":"511 U.S. 513","y":1994,"id":"1993/92-903","sc":1,"op":1,"sum":"Upon searching petitioner Acty's residence and the premises of her business, petitioner Posters 'N' Things, Ltd., officers seized, among other things, pipes, \"bongs,\" scales, \"roach clips,\" drug diluents, and advertisements describing various drug-related products sold by petitioners. Petitioners were indicted on, and convicted in the District Court of, a number of charges, including the use of an interstate …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Raley v. Ohio","cite":"360 U.S. 423","y":1959,"id":"1958/175","sc":1,"sum":"The four appellants were convicted in state courts for refusing to answer questions about Communistic or subversive activities put to them at sessions of the \"Un-American Activities Commission\" established in the legislative branch of the Ohio Government. Each was led by the Commission to believe that the privilege against self-incrimination afforded by the Ohio Constitution was generally available to him, and each …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Regan v. Wald","cite":"468 U.S. 222","y":1984,"id":"1983/83-436","sc":1,"op":2,"ar":3,"sum":"Upholding President’s decision to impose travel ban to Cuba “to curtail the ﬂow of hard currency to Cuba— currency that could then be used in support of Cuban adven­ turism”.","sumSrc":"opinion","by":{"0":"57"}},{"t":"case","label":"Reno v. ACLU","cite":"521 U.S. 844","y":1997,"id":"1996/96-511","sc":1,"sum":"The Court ruled that certain provisions of the Communications Decency Act concerning \"indecent\" behavior were unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"31, 45"}},{"t":"case","label":"Scales v. United States","cite":"367 U.S. 203","y":1961,"id":"1960/1","sc":1,"op":8,"ar":3,"sum":"Scales was prosecuted and convicted of a felony for his membership in the Communist Party, which advocated the violent overthrow of the government, and was illegal under the Smith Act.","sumSrc":"Oyez","by":{"0":"36, 64, 65, 66"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"0":"62"}},{"t":"case","label":"Staples v. United States","cite":"511 U.S. 600","y":1994,"id":"1993/92-1441","sc":1,"sum":"To obtain a § 5861(d) conviction, the Government should have been required to prove beyond a reasonable doubt that Staples knew that his rifle had the characteristics that brought it within the statutory definition of a machinegun.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"64"}},{"t":"case","label":"Taylor v. Louisiana","cite":"419 U.S. 522","y":1975,"id":"1974/73-5744","sc":1,"sum":"The Court held that a jury made up of a representative cross-section of the community is an essential component of the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Third Nat’l Bank v. Impac Ltd.","cite":"432 U.S. 312","y":1977,"id":"1976/76-674","sc":1,"op":4,"sum":"Title 12 U. S. C. § 91, which prohibits an \"attachment, injunction, or execution\" from being issued against a national bank or its property before final judgment in any state or local court, held, when read in context, merely to prevent prejudgment seizure of bank property by creditors and not to apply to a mortgagor-debtor's action seeking a preliminary injunction to protect its real property from wrongful …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Turner Broad. Sys., Inc. v. FCC","cite":"520 U.S. 180","y":1997,"id":"1996/95-992","sc":1,"op":2,"sum":"In a 5-to-4 decision, the Court held that Congress \"has an independent interest in preserving a multiplicity of broadcasters.\" The outcome supported Congress's right to judge what approach would best insure a competitive communications marketplace.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"United States v. Al-Arian","cite":"308 F. Supp. 2d 1322","y":2004,"court":"M.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/308/1322/","by":{"0":"65"}},{"t":"case","label":"United States v. Albertini","cite":"472 U.S. 675","y":1985,"id":"1984/83-1624","sc":1,"sum":"Title 18 U. S. C. § 1382 makes it unlawful to reenter a military base after having been \"ordered not to reenter by any officer in command or charge thereof.\" In 1972, respondent received from the commanding officer of Hickam Air Force Base in Hawaii a letter (bar letter) forbidding him to reenter the base without written permission from the commanding officer or his designate. The letter was issued after respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46, 52"}},{"t":"case","label":"United States v. Alves","cite":"317 F. Supp. 2d 65","y":2004,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/317/65/","sum":"Construing the term “expert or other services” to include “[t]he services of an immigration counsel”.","sumSrc":"brief:0","by":{"0":"27"}},{"t":"case","label":"United States v. Assi","cite":"414 F. Supp. 2d 707","y":2006,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/414/707/","by":{"0":"58"}},{"t":"case","label":"United States v. Awan","cite":"459 F. Supp. 2d 167","y":2006,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/459/167/","by":{"0":"36, 58"}},{"t":"case","label":"United States v. Balint","cite":"258 U.S. 250","y":1922,"id":"scdb/1921-077","sc":1,"by":{"0":"64"}},{"t":"case","label":"United States v. Bestfoods","cite":"524 U.S. 51","y":1998,"id":"1997/97-454","sc":1,"sum":"But a corporate parent that actively participated in, and exercised control over, the operations of the facility itself may be held directly liable in its own right as an operator of the facility.","sumSrc":"Oyez","by":{"0":"63"}},{"t":"case","label":"United States v. Cardiff","cite":"344 U.S. 174","y":1952,"id":"scdb/1952-021","sc":1,"sum":"It is not an offense under §§ 301 (f) and 704 of the Federal Food, Drug, and Cosmetic Act for the president of a corporation operating a factory engaged in packing and preparing food for interstate distribution to refuse -to grant permission for inspectors of the Food and Drug Administration to enter and inspect the factory at reasonable times. Pp. 174-177. 194 F. 2d 686, affirmed. Respondent was convicted of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"United States v. Goba","cite":"220 F. Supp. 2d 182","y":2002,"court":"W.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/220/182/","by":{"0":"36"}},{"t":"case","label":"United States v. Hammoud","cite":"381 F.3d 316","y":2004,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/381/316/","by":{"0":"48, 52, 54, 58, 59, 65"}},{"t":"case","label":"United States v. Hescorp, Heavy Equip. Sales Corp.","cite":"801 F.3d 70","y":1986,"url":"https://www.courtlistener.com/c/F.3d/801/70/","by":{"0":"38"}},{"t":"case","label":"United States v. Kandasamy","cite":"2008 WL 2660610","y":2008,"court":"E.D.N.Y. July 3","by":{"0":"53"}},{"t":"case","label":"United States v. Kassir","cite":"2009 WL 2913651","y":2009,"court":"S.D.N.Y. Sept. 11","by":{"0":"53"}},{"t":"case","label":"United States v. Lindh","cite":"212 F. Supp. 2d 541","y":2002,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/212/541/","by":{"0":"36"}},{"t":"case","label":"United States v. Marzook","cite":"383 F. Supp. 2d 2056","y":2005,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/383/2056/","by":{"0":"36, 58"}},{"t":"case","label":"United States v. Moses","cite":"137 F.3d 894","y":1998,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/137/894/","sum":"Construing the term “expert testimony” in 18 U.S.C. 3509(b)(1)(B)(ii) to mean testimony by a “person with a high degree of skill or knowledge of a certain subject”.","sumSrc":"brief:0","by":{"0":"27"}},{"t":"case","label":"United States v. O’Brien","cite":"391 U.S. 367","y":1968,"id":"1967/232","sc":1,"op":8,"sum":"The Court found that it was not an infringement on one's First Amendment rights to criminalize burning a draft card.","sumSrc":"Oyez","by":{"0":"15, 49, 52, 53"}},{"t":"case","label":"United States v. Riverside Bayview Homes, Inc.","cite":"474 U.S. 121","y":1985,"id":"1985/84-701","sc":1,"sum":"The Clean Water Act prohibits any discharge of dredged or fill materials into \"navigable waters\"-defined as the \"waters of the United States\"unless authorized by a permit issued by the Army Corps of Engineers (Corps). Construing the Act to cover all \"freshwater wetlands\" that are adjacent to other covered waters, the Corps issued a regulation defining such wetlands as \"those areas that are inundated or saturated by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"United States v. Robel","cite":"389 U.S. 258","y":1967,"id":"1967/8","sc":1,"op":6,"sum":"The Supreme Court held that the provision was overbroad and the war power does not give Congress a blank slate to do whatever it wants. Justice William J. Brennan concurred in the judgment, writing that Congress’ delegation of authority in designating defense facilities to the Secretary of Defense was unconstitutional because they provided no meaningful standards for the Secretary to follow.","sumSrc":"Oyez","by":{"0":"60"}},{"t":"case","label":"United States v. Sattar","cite":"272 F. Supp. 2d 348","y":2003,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/272/348/","by":{"0":"37, 58"}},{"t":"case","label":"United States v. Shah","cite":"474 F. Supp. 2d 492","y":2007,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/474/492/","by":{"0":"36, 58"}},{"t":"case","label":"United States v. Taleb-Jedi","cite":"566 F. Supp. 2d 157","y":2008,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/566/157/","by":{"0":"35, 54, 58"}},{"t":"case","label":"United States v. Warsame","cite":"537 F. Supp. 2d 1005","y":2008,"court":"D. Minn.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/537/1005/","by":{"0":"36, 58, 65"}},{"t":"case","label":"United States v. Williams","cite":"128 S. Ct. 1830","y":2008,"id":"2007/06-694","sc":1,"op":5,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"0":"14, 18, 24, 25, 31, 32, 36, 42, 57"}},{"t":"case","label":"United States ex rel. the Attorney General of the United States v. Delaware & Hudson Co.","cite":"213 U.S. 366","y":1909,"id":"scdb/1908-137","sc":1,"sum":"Although a limitation to its operation might be reasonable and thus assuage the radical results of a prohibitory statute, if it is not'.expressed in the-statute-, to engraft such a limitation would be.pure-judicial legislation: IÁ construing the commodities clause of the Hepburn Act the\"suggestion' of the Government to limit its application to commodities while in the'hánds of a carrier or its first vendee, and, as …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Village of Hoffman Estates v. Flipside, Hoffman Estates, Inc.","cite":"455 U.S. 489","y":1982,"id":"1981/80-1681","sc":1,"op":5,"sum":"The ordinance is not facially overbroad or vague but is reasonably clear in its application to appellee.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 19, 26, 34"}},{"t":"case","label":"Virginia v. Hicks","cite":"539 U.S. 113","y":2003,"id":"2002/02-371","sc":1,"op":1,"sum":"The Court held that the RRHA's trespass policy is not facially invalid under the First Amendment's overbreadth doctrine.","sumSrc":"Oyez","by":{"0":"43, 57, 58, 59"}},{"t":"case","label":"Ward v. Rock Against Racism","cite":"491 U.S. 781","y":1989,"id":"1988/88-226","sc":1,"op":2,"sum":"The Court upheld the ordinance, giving broad deference to the government's interest in maintaining order. As long as \"the means chosen are not substantially broader than necessary to achieve the government's interest,\" a regulation will not be invalidated because a court concludes that the government's interest \"could be adequately served by some less-speech-restrictive alternative.\".","sumSrc":"Oyez","by":{"0":"18, 48, 51"}},{"t":"case","label":"Wayte v. United States","cite":"470 U.S. 598","y":1985,"id":"1984/83-1292","sc":1,"sum":"The Supreme Court held, 7-to-2, that the government's passive enforcement policy was constitutional.","sumSrc":"Oyez","by":{"0":"49, 53"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"passim"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"2, 13, 15, 16, 43, 62, 63"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"2"}},{"t":"law","label":"Pub. L. No. 108-458","url":"https://www.govinfo.gov/link/plaw/108/public/458","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/15/1","by":{"0":"35"}},{"t":"usc","label":"18 U.S.C. § 2385","url":"https://www.law.cornell.edu/uscode/text/18/2385","by":{"0":"65"}},{"t":"usc","label":"5 U.S.C. § 3323","url":"https://www.law.cornell.edu/uscode/text/5/3323","subs":["(d)"],"by":{"0":"28"}},{"t":"usc","label":"5 U.S.C. § 4103","url":"https://www.law.cornell.edu/uscode/text/5/4103","subs":["(a)"],"by":{"0":"20"}},{"t":"usc","label":"6 U.S.C. § 236","url":"https://www.law.cornell.edu/uscode/text/6/236","subs":["(e)(2)(A)"],"by":{"0":"28"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(3)(B)","(a)(3)(B)(iv)(VI)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"3, 20"}},{"t":"usc","label":"8 U.S.C. § 1189","url":"https://www.law.cornell.edu/uscode/text/8/1189","subs":["(a)(1)","(c)","(d)(4)"],"stext":{"head":"§1189. Designation of foreign terrorist organizations","paras":[[0,"(a) Designation"],[0,"(1) In general"],[1,"The Secretary is authorized to designate an organization as a foreign terrorist organization in accordance with this subsection if the Secretary finds that—"],[2,"(A) the organization is a foreign organization;"],[2,"(B) the organization engages in terrorist activity (as defined in section 1182(a)(3)(B) of this title or terrorism (as defined in section 2656f(d)(2) of title 22), or retains the capability and intent to engage in terrorist activity or terrorism) 1; and"],[2,"(C) the terrorist activity or terrorism of the organization threatens the security of United States nationals or the national security of the United States."],[0,"(2) Procedure"],[0,"(A) Notice"],[0,"(i) To congressional leaders"],[3,"Seven days before making a designation under this subsection, the Secretary shall, by classified communication, notify the Speaker and Minority Leader of the House of Representatives, the President pro tempore, Majority Leader, and Minority Leader of the Senate, and the members of the relevant committees of the House of Representatives and the Senate, in writing, of the intent to designate an organization under this subsection, together with the findings made under paragraph (1) with respect to that organization, and the factual basis therefor."],[0,"(ii) Publication in Federal Register"],[3,"The Secretary shall publish the designation in the Federal Register seven days after providing the notification under clause (i)."],[0,"(B) Effect of designation"],[2,"(i) For purposes of section 2339B of title 18, a designation under this subsection shall take effect upon publication under subparagraph (A)(ii)."],[2,"(ii) Any designation under this subsection shall cease to have effect upon an Act of Congress disapproving such designation."],[0,"(C) Freezing of assets"],[2,"Upon notification under paragraph (2)(A)(i), the Secretary of the Treasury may require United States financial institutions possessing or controlling any assets of any foreign organization included in the notification to block all financial transactions involving those assets until further directive from either the Secretary of the Treasury, Act of Congress, or order of court."],[0,"(3) Record"],[0,"(A) In general"],[2,"In making a designation under this subsection, the Secretary shall create an administrative record."],[0,"(B) Classified information"],[2,"The Secretary may consider classified information in making a designation under this subsection. Classified information shall not be subject to disclosure for such time as it remains classified, except that such information may be disclosed to a court ex parte and in camera for purposes of judicial review under subsection (c)."],[0,"(4) Period of designation"],[0,"(A) In general"],[2,"A designation under this subsection shall be effective for all purposes until revoked under paragraph (5) or (6) or set aside pursuant to subsection (c)."],[0,"(B) Review of designation upon petition"],[0,"(i) In general"],[3,"The Secretary shall review the designation of a foreign terrorist organization under the procedures set forth in clauses (iii) and (iv) if the designated organization files a petition for revocation within the petition period described in clause (ii)."],[0,"(ii) Petition period"],[3,"For purposes of clause (i)—"],[4,"(I) if the designated organization has not previously filed a petition for revocation under this subparagraph, the petition period begins 2 years after the date on which the designation was made; or"],[4,"(II) if the designated organization has previously filed a petition for revocation under this subparagraph, the petition period begins 2 years after the date of the determination made under clause (iv) on that petition."],[0,"(iii) Procedures"],[3,"Any foreign terrorist organization that submits a petition for revocation under this subparagraph must provide evidence in that petition that the relevant circumstances described in paragraph (1) are sufficiently different from the circumstances that were the basis for the designation such that a revocation with respect to the organization is warranted."],[0,"(iv) Determination"],[0,"(I) In general"],[4,"Not later than 180 days after receiving a petition for revocation submitted under this subparagraph, the Secretary shall make a determination as to such revocation."],[0,"(II) Classified information"],[4,"The Secretary may consider classified information in making a determination in response to a petition for revocation. Classified information shall not be subject to disclosure for such time as it remains classified, except that such information may be disclosed to a court ex parte and in camera for purposes of judicial review under subsection (c)."],[0,"(III) Publication of determination"],[4,"A determination made by the Secretary under this clause shall be published in the Federal Register."],[0,"(IV) Procedures"],[4,"Any revocation by the Secretary shall be made in accordance with paragraph (6)."],[0,"(C) Other review of designation"],[0,"(i) In general"],[3,"If in a 5-year period no review has taken place under subparagraph (B), the Secretary shall review the designation of the foreign terrorist organization in order to determine whether such designation should be revoked pursuant to paragraph (6)."],[0,"(ii) Procedures"],[3,"If a review does not take place pursuant to subparagraph (B) in response to a petition for revocation that is filed in accordance with that subparagraph, then the review shall be conducted pursuant to procedures established by the Secretary. The results of such review and the applicable procedures shall not be reviewable in any court."],[0,"(iii) Publication of results of review"],[3,"The Secretary shall publish any determination made pursuant to this subparagraph in the Federal Register."],[0,"(5) Revocation by Act of Congress"],[1,"The Congress, by an Act of Congress, may block or revoke a designation made under paragraph (1)."],[0,"(6) Revocation based on change in circumstances"],[0,"(A) In general"],[2,"The Secretary may revoke a designation made under paragraph (1) at any time, and shall revoke a designation upon completion of a review conducted pursuant to subparagraphs (B) and (C) of paragraph (4) if the Secretary finds that—"],[3,"(i) the circumstances that were the basis for the designation have changed in such a manner as to warrant revocation; or"],[3,"(ii) the national security of the United States warrants a revocation."],[0,"(B) Procedure"],[2,"The procedural requirements of paragraphs (2) and (3) shall apply to a revocation under this paragraph. Any revocation shall take effect on the date specified in the revocation or upon publication in the Federal Register if no effective date is specified."],[0,"(7) Effect of revocation"],[1,"The revocation of a designation under paragraph (5) or (6) shall not affect any action or proceeding based on conduct committed prior to the effective date of such revocation."],[0,"(8) Use of designation in trial or hearing"],[1,"If a designation under this subsection has become effective under paragraph (2)(B) a defendant in a criminal action or an alien in a removal proceeding shall not be permitted to raise any question concerning the validity of the issuance of such designation as a defense or an objection at any trial or hearing."],[0,"(b) Amendments to a designation"],[0,"(1) In general"],[1,"The Secretary may amend a designation under this subsection if the Secretary finds that the organization has changed its name, adopted a new alias, dissolved and then reconstituted itself under a different name or names, or merged with another organization."],[0,"(2) Procedure"],[1,"Amendments made to a designation in accordance with paragraph (1) shall be effective upon publication in the Federal Register. Subparagraphs (B) and (C) of subsection (a)(2) shall apply to an amended designation upon such publication. Paragraphs (2)(A)(i), (4), (5), (6), (7), and (8) of subsection (a) shall also apply to an amended designation."],[0,"(3) Administrative record"],[1,"The administrative record shall be corrected to include the amendments as well as any additional relevant information that supports those amendments."],[0,"(4) Classified information"],[1,"The Secretary may consider classified information in amending a designation in accordance with this subsection. Classified information shall not be subject to disclosure for such time as it remains classified, except that such information may be disclosed to a court ex parte and in camera for purposes of judicial review under subsection (c)."],[0,"(c) Judicial review of designation"],[0,"(1) In general"],[1,"Not later than 30 days after publication in the Federal Register of a designation, an amended designation, or a determination in response to a petition for revocation, the designated organization may seek judicial review in the United States Court of Appeals for the District of Columbia Circuit."],[0,"(2) Basis of review"],[1,"Review under this subsection shall be based solely upon the administrative record, except that the Government may submit, for ex parte and in camera review, classified information used in making the designation, amended designation, or determination in response to a petition for revocation."],[0,"(3) Scope of review"],[1,"The Court shall hold unlawful and set aside a designation, amended designation, or determination in response to a petition for revocation the court finds to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1189?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1189. Designation of foreign terrorist organizations","tname":"Aliens and Nationality","by":{"0":"3, 50, 3, 59, 3"}},{"t":"usc","label":"10 U.S.C. § 373","url":"https://www.law.cornell.edu/uscode/text/10/373","subs":["(2)"],"by":{"0":"28"}},{"t":"usc","label":"12 U.S.C. § 1828","url":"https://www.law.cornell.edu/uscode/text/12/1828","subs":["(l)"],"by":{"0":"23"}},{"t":"usc","label":"15 U.S.C. § 3116","url":"https://www.law.cornell.edu/uscode/text/15/3116","by":{"0":"20"}},{"t":"usc","label":"18 U.S.C. § 175b","url":"https://www.law.cornell.edu/uscode/text/18/175b","subs":["(d)(2)(G)"],"by":{"0":"35"}},{"t":"usc","label":"18 U.S.C. § 225","url":"https://www.law.cornell.edu/uscode/text/18/225","subs":["(a)(1)"],"by":{"0":"35"}},{"t":"usc","label":"18 U.S.C. § 951","url":"https://www.law.cornell.edu/uscode/text/18/951","subs":["(d)"],"by":{"0":"35"}},{"t":"usc","label":"18 U.S.C. § 1169","url":"https://www.law.cornell.edu/uscode/text/18/1169","subs":["(b)(1)"],"by":{"0":"35"}},{"t":"usc","label":"18 U.S.C. § 1960","url":"https://www.law.cornell.edu/uscode/text/18/1960","subs":["(a)"],"by":{"0":"35"}},{"t":"usc","label":"18 U.S.C. § 2339A","url":"https://www.law.cornell.edu/uscode/text/18/2339A","subs":["(a)","(b)(1)","(b)(2)","(b)(3)"],"stext":{"head":"§2339A. Providing material support to terrorists","paras":[[0,"(a) Offense.—Whoever provides material support or resources or conceals or disguises the nature, location, source, or ownership of material support or resources, knowing or intending that they are to be used in preparation for, or in carrying out, a violation of section 32, 37, 81, 175, 229, 351, 831, 842(m) or (n), 844(f) or (i), 930(c), 956, 1091, 1114, 1116, 1203, 1361, 1362, 1363, 1366, 1751, 1992, 2155, 2156, 2280, 2281, 2332, 2332a, 2332b, 2332f, 2340A, or 2442 of this title, section 236 of the Atomic Energy Act of 1954 (42 U.S.C. 2284), section 46502 or 60123(b) of title 49, or any offense listed in section 2332b(g)(5)(B) (except for sections 2339A and 2339B) or in preparation for, or in carrying out, the concealment of an escape from the commission of any such violation, or attempts or conspires to do such an act, shall be fined under this title, imprisoned not more than 15 years, or both, and, if the death of any person results, shall be imprisoned for any term of years or for life. A violation of this section may be prosecuted in any Federal judicial district in which the underlying offense was committed, or in any other Federal judicial district as provided by law."],[0,"(b) Definitions.—As used in this section—"],[1,"(1) the term \"material support or resources\" means any property, tangible or intangible, or service, including currency or monetary instruments or financial securities, financial services, lodging, training, expert advice or assistance, safehouses, false documentation or identification, communications equipment, facilities, weapons, lethal substances, explosives, personnel (1 or more individuals who may be or include oneself), and transportation, except medicine or religious materials;"],[1,"(2) the term \"training\" means instruction or teaching designed to impart a specific skill, as opposed to general knowledge; and"],[1,"(3) the term \"expert advice or assistance\" means advice or assistance derived from scientific, technical or other specialized knowledge."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2339A?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2339A. Providing material support to terrorists","tname":"Crimes and Criminal Procedure","by":{"0":"46, 64, 64, 4, 13, 17 , 20, 32, 39, 46, 51, 4, 21, 4, 11, 29, 31, 32"}},{"t":"usc","label":"18 U.S.C. § 2339B","url":"https://www.law.cornell.edu/uscode/text/18/2339B","subs":["(a)","(a)(1)","(h)"],"stext":{"head":"§2339B. Providing material support or resources to designated foreign terrorist organizations","paras":[[0,"(a) Prohibited Activities.—"],[1,"(1) Unlawful conduct.—Whoever knowingly provides material support or resources to a foreign terrorist organization, or attempts or conspires to do so, shall be fined under this title or imprisoned not more than 20 years, or both, and, if the death of any person results, shall be imprisoned for any term of years or for life. To violate this paragraph, a person must have knowledge that the organization is a designated terrorist organization (as defined in subsection (g)(6)), that the organization has engaged or engages in terrorist activity (as defined in section 212(a)(3)(B) of the Immigration and Nationality Act), or that the organization has engaged or engages in terrorism (as defined in section 140(d)(2) of the Foreign Relations Authorization Act, Fiscal Years 1988 and 1989)."],[1,"(2) Financial institutions.—Except as authorized by the Secretary, any financial institution that becomes aware that it has possession of, or control over, any funds in which a foreign terrorist organization, or its agent, has an interest, shall—"],[2,"(A) retain possession of, or maintain control over, such funds; and"],[2,"(B) report to the Secretary the existence of such funds in accordance with regulations issued by the Secretary."],[0,"(b) Civil Penalty.—Any financial institution that knowingly fails to comply with subsection (a)(2) shall be subject to a civil penalty in an amount that is the greater of—"],[1,"(A) $50,000 per violation; or"],[1,"(B) twice the amount of which the financial institution was required under subsection (a)(2) to retain possession or control."],[0,"(c) Injunction.—Whenever it appears to the Secretary or the Attorney General that any person is engaged in, or is about to engage in, any act that constitutes, or would constitute, a violation of this section, the Attorney General may initiate civil action in a district court of the United States to enjoin such violation."],[0,"(d) Extraterritorial Jurisdiction.—"],[1,"(1) In general.—There is jurisdiction over an offense under subsection (a) if—"],[2,"(A) an offender is a national of the United States (as defined in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22))) or an alien lawfully admitted for permanent residence in the United States (as defined in section 101(a)(20) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(20)));"],[2,"(B) an offender is a stateless person whose habitual residence is in the United States;"],[2,"(C) after the conduct required for the offense occurs an offender is brought into or found in the United States, even if the conduct required for the offense occurs outside the United States;"],[2,"(D) the offense occurs in whole or in part within the United States;"],[2,"(E) the offense occurs in or affects interstate or foreign commerce; or"],[2,"(F) an offender aids or abets any person over whom jurisdiction exists under this paragraph in committing an offense under subsection (a) or conspires with any person over whom jurisdiction exists under this paragraph to commit an offense under subsection (a)."],[1,"(2) Extraterritorial jurisdiction.—There is extraterritorial Federal jurisdiction over an offense under this section."],[0,"(e) Investigations.—"],[1,"(1) In general.—The Attorney General shall conduct any investigation of a possible violation of this section, or of any license, order, or regulation issued pursuant to this section."],[1,"(2) Coordination with the department of the treasury.—The Attorney General shall work in coordination with the Secretary in investigations relating to—"],[2,"(A) the compliance or noncompliance by a financial institution with the requirements of subsection (a)(2); and"],[2,"(B) civil penalty proceedings authorized under subsection (b)."],[1,"(3) Referral.—Any evidence of a criminal violation of this section arising in the course of an investigation by the Secretary or any other Federal agency shall be referred immediately to the Attorney General for further investigation. The Attorney General shall timely notify the Secretary of any action taken on referrals from the Secretary, and may refer investigations to the Secretary for remedial licensing or civil penalty action."],[0,"(f) Classified Information in Civil Proceedings Brought by the United States.—"],[1,"(1) Discovery of classified information by defendants.—"],[2,"(A) Request by united states.—In any civil proceeding under this section, upon request made ex parte and in writing by the United States, a court, upon a sufficient showing, may authorize the United States to—"],[3,"(i) redact specified items of classified information from documents to be introduced into evidence or made available to the defendant through discovery under the Federal Rules of Civil Procedure;"],[3,"(ii) substitute a summary of the information for such classified documents; or"],[3,"(iii) substitute a statement admitting relevant facts that the classified information would tend to prove."],[2,"(B) Order granting request.—If the court enters an order granting a request under this paragraph, the entire text of the documents to which the request relates shall be sealed and preserved in the records of the court to be made available to the appellate court in the event of an appeal."],[2,"(C) Denial of request.—If the court enters an order denying a request of the United States under this paragraph, the United States may take an immediate, interlocutory appeal in accordance with paragraph (5). For purposes of such an appeal, the entire text of the documents to which the request relates, together with any transcripts of arguments made ex parte to the court in connection therewith, shall be maintained under seal and delivered to the appellate court."],[1,"(2) Introduction of classified information; precautions by court.—"],[2,"(A) Exhibits.—To prevent unnecessary or inadvertent disclosure of classified information in a civil proceeding brought by the United States under this section, the United States may petition the court ex parte to admit, in lieu of classified writings, recordings, or photographs, one or more of the following:"],[3,"(i) Copies of items from which classified information has been redacted."],[3,"(ii) Stipulations admitting relevant facts that specific classified information would tend to prove."],[3,"(iii) A declassified summary of the specific classified information."],[2,"(B) Determination by court.—The court shall grant a request under this paragraph if the court finds that the redacted item, stipulation, or summary is sufficient to allow the defendant to prepare a defense."],[1,"(3) Taking of trial testimony.—"],[2,"(A) Objection.—During the examination of a witness in any civil proceeding brought by the United States under this subsection, the United States may object to any question or line of inquiry that may require the witness to disclose classified information not previously found to be admissible."],[2,"(B) Action by court.—In determining whether a response is admissible, the court shall take precautions to guard against the compromise of any classified information, including—"],[3,"(i) permitting the United States to provide the court, ex parte, with a proffer of the witness's response to the question or line of inquiry; and"],[3,"(ii) requiring the defendant to provide the court with a proffer of the nature of the information that the defendant seeks to elicit."],[2,"(C) Obligation of defendant.—In any civil proceeding under this section, it shall be the defendant's obligation to establish the relevance and materiality of any classified information sought to be introduced."],[1,"(4) Appeal.—If the court enters an order denying a request of the United States under this subsection, the United States may take an immediate interlocutory appeal in accordance with paragraph (5)."],[1,"(5) Interlocutory appeal.—"],[2,"(A) Subject of appeal.—An interlocutory appeal by the United States shall lie to a court of appeals from a decision or order of a district court—"],[3,"(i) authorizing the disclosure of classified information;"],[3,"(ii) imposing sanctions for nondisclosure of classified information; or"],[3,"(iii) refusing a protective order sought by the United States to prevent the disclosure of classified information."],[2,"(B) Expedited consideration.—"],[3,"(i) In general.—An appeal taken pursuant to this paragraph, either before or during trial, shall be expedited by the court of appeals."],[3,"(ii) Appeals prior to trial.—If an appeal is of an order made prior to trial, an appeal shall be taken not later than 14 days after the decision or order appealed from, and the trial shall not commence until the appeal is resolved."],[3,"(iii) Appeals during trial.—If an appeal is taken during trial, the trial court shall adjourn the trial until the appeal is resolved, and the court of appeals—"],[4,"(I) shall hear argument on such appeal not later than 4 days after the adjournment of the trial, excluding intermediate weekends and holidays;"],[4,"(II) may dispense with written briefs other than the supporting materials previously submitted to the trial court;"],[4,"(III) shall render its decision not later than 4 days after argument on appeal, excluding intermediate weekends and holidays; and"],[4,"(IV) may dispense with the issuance of a written opinion in rendering its decision."],[2,"(C) Effect of ruling.—An interlocutory appeal and decision shall not affect the right of the defendant, in a subsequent appeal from a final judgment, to claim as error reversal by the trial court on remand of a ruling appealed from during trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2339B?type=usc&year=mostrecent&link-type=html"},"op":51,"head":"§2339B. Providing material support or resources to designated foreign terrorist organizations","tname":"Crimes and Criminal Procedure","by":{"0":"passim, 10, 3, 4, 13, 22, 32, 39, 64, 4, 12, 35, 36, 37, 38"}},{"t":"usc","label":"18 U.S.C. § 2339C","url":"https://www.law.cornell.edu/uscode/text/18/2339C","subs":["(a)(1)"],"stext":{"head":"§2339C. Prohibitions against the financing of terrorism","paras":[[0,"(a) Offenses.—"],[1,"(1) In general.—Whoever, in a circumstance described in subsection (b), by any means, directly or indirectly, unlawfully and willfully provides or collects funds with the intention that such funds be used, or with the knowledge that such funds are to be used, in full or in part, in order to carry out—"],[2,"(A) an act which constitutes an offense within the scope of a treaty specified in subsection (e)(7), as implemented by the United States, or"],[2,"(B) any other act intended to cause death or serious bodily injury to a civilian, or to any other person not taking an active part in the hostilities in a situation of armed conflict, when the purpose of such act, by its nature or context, is to intimidate a population, or to compel a government or an international organization to do or to abstain from doing any act,"],[1,"shall be punished as prescribed in subsection (d)(1)."],[1,"(2) Attempts and conspiracies.—Whoever attempts or conspires to commit an offense under paragraph (1) shall be punished as prescribed in subsection (d)(1)."],[1,"(3) Relationship to predicate act.—For an act to constitute an offense set forth in this subsection, it shall not be necessary that the funds were actually used to carry out a predicate act."],[0,"(b) Jurisdiction.—There is jurisdiction over the offenses in subsection (a) in the following circumstances—"],[1,"(1) the offense takes place in the United States and—"],[2,"(A) a perpetrator was a national of another state or a stateless person;"],[2,"(B) on board a vessel flying the flag of another state or an aircraft which is registered under the laws of another state at the time the offense is committed;"],[2,"(C) on board an aircraft which is operated by the government of another state;"],[2,"(D) a perpetrator is found outside the United States;"],[2,"(E) was directed toward or resulted in the carrying out of a predicate act against—"],[3,"(i) a national of another state; or"],[3,"(ii) another state or a government facility of such state, including its embassy or other diplomatic or consular premises of that state;"],[2,"(F) was directed toward or resulted in the carrying out of a predicate act committed in an attempt to compel another state or international organization to do or abstain from doing any act; or"],[2,"(G) was directed toward or resulted in the carrying out of a predicate act—"],[3,"(i) outside the United States; or"],[3,"(ii) within the United States, and either the offense or the predicate act was conducted in, or the results thereof affected, interstate or foreign commerce;"],[1,"(2) the offense takes place outside the United States and—"],[2,"(A) a perpetrator is a national of the United States or is a stateless person whose habitual residence is in the United States;"],[2,"(B) a perpetrator is found in the United States; or"],[2,"(C) was directed toward or resulted in the carrying out of a predicate act against—"],[3,"(i) any property that is owned, leased, or used by the United States or by any department or agency of the United States, including an embassy or other diplomatic or consular premises of the United States;"],[3,"(ii) any person or property within the United States;"],[3,"(iii) any national of the United States or the property of such national; or"],[3,"(iv) any property of any legal entity organized under the laws of the United States, including any of its States, districts, commonwealths, territories, or possessions;"],[1,"(3) the offense is committed on board a vessel flying the flag of the United States or an aircraft which is registered under the laws of the United States at the time the offense is committed;"],[1,"(4) the offense is committed on board an aircraft which is operated by the United States; or"],[1,"(5) the offense was directed toward or resulted in the carrying out of a predicate act committed in an attempt to compel the United States to do or abstain from doing any act."],[0,"(c) Concealment.—Whoever—"],[1,"(1)(A) is in the United States; or"],[1,"(B) is outside the United States and is a national of the United States or a legal entity organized under the laws of the United States (including any of its States, districts, commonwealths, territories, or possessions); and"],[1,"(2) knowingly conceals or disguises the nature, location, source, ownership, or control of any material support or resources, or any funds or proceeds of such funds—"],[2,"(A) knowing or intending that the support or resources are to be provided, or knowing that the support or resources were provided, in violation of section 2339B of this title; or"],[2,"(B) knowing or intending that any such funds are to be provided or collected, or knowing that the funds were provided or collected, in violation of subsection (a),"],[0,"shall be punished as prescribed in subsection (d)(2)."],[0,"(d) Penalties.—"],[1,"(1) Subsection (a).—Whoever violates subsection (a) shall be fined under this title, imprisoned for not more than 20 years, or both."],[1,"(2) Subsection (c).—Whoever violates subsection (c) shall be fined under this title, imprisoned for not more than 10 years, or both."],[0,"(e) Definitions.—In this section—"],[1,"(1) the term \"funds\" means assets of every kind, whether tangible or intangible, movable or immovable, however acquired, and legal documents or instruments in any form, including electronic or digital, evidencing title to, or interest in, such assets, including coin, currency, bank credits, travelers checks, bank checks, money orders, shares, securities, bonds, drafts, and letters of credit;"],[1,"(2) the term \"government facility\" means any permanent or temporary facility or conveyance that is used or occupied by representatives of a state, members of a government, the legislature, or the judiciary, or by officials or employees of a state or any other public authority or entity or by employees or officials of an intergovernmental organization in connection with their official duties;"],[1,"(3) the term \"proceeds\" means any funds derived from or obtained, directly or indirectly, through the commission of an offense set forth in subsection (a);"],[1,"(4) the term \"provides\" includes giving, donating, and transmitting;"],[1,"(5) the term \"collects\" includes raising and receiving;"],[1,"(6) the term \"predicate act\" means any act referred to in subparagraph (A) or (B) of subsection (a)(1);"],[1,"(7) the term \"treaty\" means—"],[2,"(A) the Convention for the Suppression of Unlawful Seizure of Aircraft, done at The Hague on December 16, 1970;"],[2,"(B) the Convention for the Suppression of Unlawful Acts against the Safety of Civil Aviation, done at Montreal on September 23, 1971;"],[2,"(C) the Convention on the Prevention and Punishment of Crimes against Internationally Protected Persons, including Diplomatic Agents, adopted by the General Assembly of the United Nations on December 14, 1973;"],[2,"(D) the International Convention against the Taking of Hostages, adopted by the General Assembly of the United Nations on December 17, 1979;"],[2,"(E) the Convention on the Physical Protection of Nuclear Material, adopted at Vienna on March 3, 1980;"],[2,"(F) the Protocol for the Suppression of Unlawful Acts of Violence at Airports Serving International Civil Aviation, supplementary to the Convention for the Suppression of Unlawful Acts against the Safety of Civil Aviation, done at Montreal on February 24, 1988;"],[2,"(G) the Convention for the Suppression of Unlawful Acts against the Safety of Maritime Navigation, done at Rome on March 10, 1988;"],[2,"(H) the Protocol for the Suppression of Unlawful Acts against the Safety of Fixed Platforms located on the Continental Shelf, done at Rome on March 10, 1988; or"],[2,"(I) the International Convention for the Suppression of Terrorist Bombings, adopted by the General Assembly of the United Nations on December 15, 1997;"],[1,"(8) the term \"intergovernmental organization\" includes international organizations;"],[1,"(9) the term \"international organization\" has the same meaning as in section 1116(b)(5) of this title;"],[1,"(10) the term \"armed conflict\" does not include internal disturbances and tensions, such as riots, isolated and sporadic acts of violence, and other acts of a similar nature;"],[1,"(11) the term \"serious bodily injury\" has the same meaning as in section 1365(g)(3) of this title; 1"],[1,"(12) the term \"national of the United States\" has the meaning given that term in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22));"],[1,"(13) the term \"material support or resources\" has the same meaning given that term in section 2339B(g)(4) of this title; and"],[1,"(14) the term \"state\" has the same meaning as that term has under international law, and includes all political subdivisions thereof."],[0,"(f) Civil Penalty.—In addition to any other criminal, civil, or administrative liability or penalty, any legal entity located within the United States or organized under the laws of the United States, including any of the laws of its States, districts, commonwealths, territories, or possessions, shall be liable to the United States for the sum of at least $10,000, if a person responsible for the management or control of that legal entity has, in that capacity, committed an offense set forth in subsection (a)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2339C?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2339C. Prohibitions against the financing of terrorism","tname":"Crimes and Criminal Procedure","by":{"0":"64, 64"}},{"t":"usc","label":"18 U.S.C. § 3509","url":"https://www.law.cornell.edu/uscode/text/18/3509","subs":["(b)(1)(B)(ii)"],"by":{"0":"27"}},{"t":"usc","label":"20 U.S.C. § 954a","url":"https://www.law.cornell.edu/uscode/text/20/954a","subs":["(b)"],"by":{"0":"20"}},{"t":"usc","label":"22 U.S.C. § 2770a","url":"https://www.law.cornell.edu/uscode/text/22/2770a","subs":["(a)"],"by":{"0":"20"}},{"t":"usc","label":"22 U.S.C. § 7423","url":"https://www.law.cornell.edu/uscode/text/22/7423","subs":["(e)"],"by":{"0":"20"}},{"t":"usc","label":"22 U.S.C. § 7432","url":"https://www.law.cornell.edu/uscode/text/22/7432","subs":["(12)"],"by":{"0":"20"}},{"t":"usc","label":"22 U.S.C. § 7611","url":"https://www.law.cornell.edu/uscode/text/22/7611","subs":["(b)(3)(A)"],"by":{"0":"23"}},{"t":"usc","label":"25 U.S.C. § 2218","url":"https://www.law.cornell.edu/uscode/text/25/2218","subs":["(g)"],"by":{"0":"23"}},{"t":"usc","label":"42 U.S.C. § 6864a","url":"https://www.law.cornell.edu/uscode/text/42/6864a","subs":["(b)(3)"],"by":{"0":"28"}},{"t":"usc","label":"42 U.S.C. § 9840a","url":"https://www.law.cornell.edu/uscode/text/42/9840a","by":{"0":"20"}},{"t":"usc","label":"42 U.S.C. § 15025","url":"https://www.law.cornell.edu/uscode/text/42/15025","by":{"0":"20"}},{"t":"usc","label":"47 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/47/504","subs":["(a)"],"by":{"0":"23"}},{"t":"rule","label":"Fed. R. Evid. 702","url":"https://www.law.cornell.edu/rules/fre/rule_702","by":{"0":"11, 29, 33"}}]};